// ── 로컬 D1 ─────────────────────────────────────────────

async function freshDb() {
  const dir = mkdtempSync(join(tmpdir(), 'agent-unit-'));
  const proxy = await getPlatformProxy<{ DB: D1Database }>({ configPath: 'wrangler.jsonc', persist: { path: dir }, remoteBindings: false });
  const db = proxy.env.DB;
  for (const f of readdirSync('migrations').filter((x) => x.endsWith('.sql')).sort())
    for (const stmt of readFileSync(join('migrations', f), 'utf8').split('--> statement-breakpoint').map((s) => s.trim()).filter(Boolean)) await db.prepare(stmt).run();
  return { db, env: proxy.env as unknown as Env, done: async () => { await proxy.dispose(); rmSync(dir, { recursive: true, force: true }); } };
}

test('D1 batch — 조건부 UPDATE 0행이면 뒤 INSERT 까지 되돌린다, 두 장치는 오류로 구분된다(28)', async () => {
  const { db, done } = await freshDb();
  try {
    await db.exec("CREATE TABLE t (id INTEGER PRIMARY KEY, status TEXT); CREATE TABLE log (msg TEXT); INSERT INTO t VALUES (1, 'pending');");
    await db.batch([db.prepare("UPDATE t SET status = 'approved' WHERE id = 1 AND status = 'pending'"), db.prepare(changedGuardSql()), db.prepare("INSERT INTO log VALUES ('approved')")]);
    let err: unknown = null;
    try {
      await db.batch([db.prepare("UPDATE t SET status = 'approved' WHERE id = 1 AND status = 'pending'"), db.prepare(changedGuardSql()), db.prepare("INSERT INTO log VALUES ('again')")]);
    } catch (e) {
      err = e;
    }
    expect(isGuardError(err)).toBe(true);
    expect((await db.prepare('SELECT msg FROM log').all()).results).toEqual([{ msg: 'approved' }]);
    await expect(db.batch([db.prepare("UPDATE t SET status = 'x' WHERE id = 99"), db.prepare('SELECT CASE WHEN changes() = 1 THEN 1 ELSE abs(-9223372036854775807 - 1) END')])).rejects.toThrow(/integer overflow/);
  } finally {
    await done();
  }
});

