/**
 * 결과물 — 에이전트가 이 공간에 저장한 초안(보고서·답변·표)을 모아 본다. 지금 볼 수 있는 실행의 것만(서버가 거른다).
 * 미리보기는 같은 출처 내려받기 주소를 글자로 읽어 보여 준다(Markdown 은 렌더, JSON·CSV 는 원문).
 */
import { useEffect, useState } from 'react';
import { Link, useSearchParams } from 'react-router';
import { useApi } from '../../lib/api';
import { useWs } from '../../app/context';
import { Empty, Loading, Markdown, PageHead } from '../../components/ui';
import { Icon } from '../../components/icons';
import { ago, fmtBytes, fmtDateTime } from '../../lib/format';
import { useFlash } from '../../lib/flash';

interface Art {
  id: string;
  title: string;
  format: 'markdown' | 'json' | 'csv';
  size: number;
  sha256: string;
  created_at: number;
  run_id: string;
  conversation_id: string | null;
  conversation_title: string | null;
  agent_name: string | null;
  trigger: string;
}

const FORMAT_LABEL: Record<Art['format'], string> = { markdown: '문서', json: 'JSON', csv: '표(CSV)' };

export function Artifacts() {
  const { ws, space, home } = useWs();
  const [params, setParams] = useSearchParams();
  const [q, setQ] = useState('');
  const list = useApi<{ artifacts: Art[] }>(space ? `/api/w/${ws}/spaces/${space}/artifacts${q ? `?q=${encodeURIComponent(q)}` : ''}` : null);
  const open = params.get('open');
  const sp = home?.spaces.find((s) => s.id === space);
  if (!space || list.isLoading) return <Loading />;
  const items = list.data?.artifacts ?? [];
  const current = items.find((x) => x.id === open) ?? null;
  return (
    <div className="content">
      <PageHead title="결과물" lead={`${sp?.kind === 'personal' ? '개인 공간' : '팀 공간'} · ${sp?.name ?? ''} — 에이전트가 저장한 보고서·답변 초안·표입니다. 외부로 보내지 않은 초안이며, 저장한 그대로 바뀌지 않습니다.`} />
      <div className="art-layout">
        <section className="card">
          <div className="card-head">
            <h2>결과물 {items.length}개</h2>
            <input className="input input--sm" type="search" aria-label="결과물 찾기" placeholder="제목·대화로 찾기" value={q} onChange={(e) => setQ(e.target.value)} />
          </div>
          {items.length === 0 ? (
            <Empty icon="file" title={q ? '찾는 결과물이 없습니다' : '아직 결과물이 없습니다'}>
              에이전트가 "초안 저장" 도구로 남긴 보고서·답변·표가 여기 모입니다.
            </Empty>
          ) : (
            <ul className="rows">
              {items.map((x) => (
                <li key={x.id}>
                  <button type="button" className={`row row--button ${x.id === open ? 'is-current' : ''}`} aria-current={x.id === open ? 'true' : undefined} onClick={() => setParams({ open: x.id })}>
                    <span className="row__icon">
                      <Icon name={x.format === 'markdown' ? 'file' : 'columns'} size={16} />
                    </span>
                    <div className="row__main">
                      <span className="row__title">{x.title}</span>
                      <span className="row__meta">
                        <span>{FORMAT_LABEL[x.format]}</span>
                        {x.agent_name && <span>{x.agent_name}</span>}
                        <span>{x.trigger === 'schedule' ? '예약 실행' : '대화'}</span>
                        <span>{ago(x.created_at)}</span>
                      </span>
                    </div>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>
        {current ? <Preview ws={ws} space={space} a={current} /> : items.length > 0 && <div className="card card-pad art-hint">왼쪽에서 결과물을 고르면 여기서 미리 봅니다.</div>}
      </div>
    </div>
  );
}

function Preview({ ws, space, a }: { ws: string; space: string; a: Art }) {
  const [text, setText] = useState<string | null>(null);
  const [err, setErr] = useState('');
  const flash = useFlash();
  const url = `/api/w/${ws}/artifacts/${a.id}/content`;
  useEffect(() => {
    let live = true;
    setText(null);
    setErr('');
    fetch(`${url}?inline=1`, { credentials: 'same-origin' })
      .then(async (r) => {
        if (!r.ok) throw new Error(String(r.status));
        const t = await r.text();
        if (live) setText(t);
      })
      .catch(() => live && setErr('결과물을 읽지 못했습니다(삭제되었거나 볼 권한이 없습니다).'));
    return () => {
      live = false;
    };
  }, [url]);
  return (
    <section className="card art-preview" aria-label="결과물 미리보기">
      <div className="card-head">
        <h2>{a.title}</h2>
        <div className="btn-row">
          <button
            type="button"
            className="btn btn-ghost btn-sm"
            disabled={text === null}
            onClick={async () => {
              await navigator.clipboard?.writeText(text ?? '').catch(() => {});
              flash.show('결과물 내용을 복사했습니다.');
            }}
          >
            복사
          </button>
          <a className="btn btn-secondary btn-sm" href={url} download>
            내려받기
          </a>
        </div>
      </div>
      <div className="card-pad">
        <p className="small muted art-meta">
          {fmtDateTime(a.created_at)} · {fmtBytes(a.size)} · SHA-256 <span className="mono">{a.sha256.slice(0, 12)}</span>
          {a.conversation_id && (
            <>
              {' · '}
              <Link to={`/app/w/${ws}/spaces/${space}/chat/${a.conversation_id}`}>대화 보기</Link>
            </>
          )}
          {' · '}
          <Link to={`/app/w/${ws}/runs/${a.run_id}`}>실행 기록</Link>
        </p>
        {err ? <p className="danger-text small">{err}</p> : text === null ? <Loading /> : a.format === 'markdown' ? <Markdown text={text} /> : <pre className="code">{text}</pre>}
      </div>
    </section>
  );
}
/**
 * 자료(지식)·파일·기억.
 * 업로드: 의도 생성(용량 예약) → 임시 R2(tmp/) → 검사(형식·크기·UTF-8·NUL·JSON 구문·SHA-256) → 보관본(files/, 새 id) → 추출 본문.
 *   임시본은 실행·내려받기에 쓰지 않는다. 같은 업로드 의도는 한 번만 쓴다. 보관본·자료 버전은 덮어쓰지 않는다.
 *   PDF·오피스·이미지(OCR)는 파서가 준비되지 않아 받지 않는다(받은 척하지 않는다).
 * 삭제: 원문·추출 본문을 비우고 R2 보관본을 지운다 — 검색·읽기·인용 표시에서 바로 빠진다.
 * 기억: 기본 꺼짐, 사용자가 직접 저장·수정·삭제. 개인 공간·본인 실행에만 쓰이고 공유 때 복제되지 않는다.
 */
import { router, body, str, ws, sp, type Ctx } from '../app';
import { Tx } from '../db/client';
import { ApiError, bad, conflict, forbidden, notFound } from '../lib/errors';
import { cleanLine, cleanText, newId, sha256Hex } from '../lib/util';
import { requireSpace, spaceAccessIn } from '../policies/access';
import { audit } from '../domain/audit';
import { FILE_POLICY, isDocumentExt } from '../../shared/domain';
import { convertDocument, documentsEnabled, DOC_MIME } from '../adapters/documents';
import { canSpace } from '../../shared/domain';

const r = router();
const MAX_TEXT = 400_000;

r.get('/w/:w/spaces/:s/knowledge', async (c) => {
  const a = await sp(c);
  const rows = await c.env.DB.prepare(
    `SELECT ks.id, ks.title, ks.tags, ks.kind, ks.visibility, ks.owner_user_id, ks.updated_at, kv.version, kv.chars, kv.sha256, kv.file_id, u.name AS owner_name
       FROM knowledge_sources ks JOIN knowledge_versions kv ON kv.id = ks.current_version_id JOIN user u ON u.id = ks.owner_user_id
      WHERE ks.workspace_id = ? AND ks.space_id = ? AND ks.status = 'active' AND (ks.visibility = 'space' OR ks.owner_user_id = ?) ORDER BY ks.updated_at DESC`,
  )
    .bind(a.workspace.id, a.space.id, a.user.id)
    .all<Record<string, unknown>>();
  return c.json({ sources: (rows.results ?? []).map((x) => ({ ...x, mine: x.owner_user_id === a.user.id })), canAdd: canSpace(a.role, a.spaceRole, 'build'), uploads: c.env.FILE_UPLOADS !== 'off', documents: documentsEnabled(c.env), policy: FILE_POLICY });
});

async function addVersion(env: Env, tx: Tx, p: { workspaceId: string; spaceId: string; sourceId: string; version: number; text: string; fileId: string | null; userId: string }) {
  const vid = newId();
  const sha = await sha256Hex(p.text);
  tx.raw(`INSERT INTO knowledge_versions (id, workspace_id, space_id, source_id, version, content_text, file_id, sha256, chars, created_by, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`, vid, p.workspaceId, p.spaceId, p.sourceId, p.version, p.text, p.fileId, sha, p.text.length, p.userId, Date.now());
  tx.raw(`UPDATE knowledge_sources SET current_version_id = ?, updated_at = ?, reviewed_at = ? WHERE id = ?`, vid, Date.now(), Date.now(), p.sourceId);
  return vid;
}

r.post('/w/:w/spaces/:s/knowledge', async (c) => {
  const a = await sp(c);
  requireSpace(a, 'build', '이 공간에 자료를 올릴 권한이 없습니다.');
  const b = await body(c);
  const title = cleanLine(str(b.title), 120);
  const text = cleanText(str(b.content), MAX_TEXT);
  if (!title || !text) throw bad('제목과 내용을 적어 주세요.');
  const kind = str(b.kind) === 'markdown' ? 'markdown' : 'text';
  const visibility = str(b.visibility) === 'private' || a.space.kind === 'personal' ? 'private' : 'space';
  const id = newId();
  const tx = new Tx(c.env);
  tx.raw(`INSERT INTO knowledge_sources (id, workspace_id, space_id, owner_user_id, title, tags, kind, visibility, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)`, id, a.workspace.id, a.space.id, a.user.id, title, cleanLine(str(b.tags), 200), kind, visibility, Date.now(), Date.now());
  await addVersion(c.env, tx, { workspaceId: a.workspace.id, spaceId: a.space.id, sourceId: id, version: 1, text, fileId: null, userId: a.user.id });
  audit(tx, { workspaceId: a.workspace.id, spaceId: a.space.id, actor: { kind: 'user', id: a.user.id }, action: 'knowledge.create', subject: { type: 'knowledge', id }, summary: `자료 추가: ${title}` });
  await tx.commit();
  return c.json({ id }, 201);
});

async function loadSource(c: Ctx, manage = false) {
  const a = await ws(c);
  const s = await c.env.DB.prepare(`SELECT * FROM knowledge_sources WHERE id = ? AND workspace_id = ? AND status = 'active'`).bind(c.req.param('id'), a.workspace.id).first<Record<string, unknown>>();
  if (!s) throw notFound();
  const access = await spaceAccessIn(c.env, a, s.space_id as string);
  if (s.visibility !== 'space' && s.owner_user_id !== a.user.id) throw notFound();
  if (manage && s.owner_user_id !== a.user.id && access.spaceRole !== 'manager') throw forbidden();
  return { a, s, access };
}

r.get('/w/:w/knowledge/:id', async (c) => {
  const { a, s } = await loadSource(c);
  const versions = await c.env.DB.prepare(`SELECT id, version, sha256, chars, file_id, created_at FROM knowledge_versions WHERE source_id = ? ORDER BY version DESC`).bind(s.id).all();
  const cur = await c.env.DB.prepare(`SELECT content_text FROM knowledge_versions WHERE id = ?`).bind(s.current_version_id).first<{ content_text: string }>();
  const agents = await c.env.DB.prepare(`SELECT DISTINCT a.id, a.name FROM agents a JOIN agent_versions v ON v.agent_id = a.id WHERE a.workspace_id = ? AND v.config_json LIKE ?`).bind(a.workspace.id, `%${s.id}%`).all();
  return c.json({ source: { ...s, mine: s.owner_user_id === a.user.id }, versions: versions.results, content: cur?.content_text ?? '', usedBy: agents.results });
});

r.post('/w/:w/knowledge/:id/versions', async (c) => {
  const { a, s } = await loadSource(c, true);
  const b = await body(c);
  const text = cleanText(str(b.content), MAX_TEXT);
  if (!text) throw bad('내용을 적어 주세요.');
  const max = await c.env.DB.prepare(`SELECT MAX(version) AS v FROM knowledge_versions WHERE source_id = ?`).bind(s.id).first<{ v: number }>();
  const tx = new Tx(c.env);
  await addVersion(c.env, tx, { workspaceId: a.workspace.id, spaceId: s.space_id as string, sourceId: s.id as string, version: (max?.v ?? 0) + 1, text, fileId: null, userId: a.user.id });
  await tx.commit();
  return c.json({ ok: true });
});

r.post('/w/:w/knowledge/:id/settings', async (c) => {
  const { a, s, access } = await loadSource(c, true);
  const b = await body(c);
  const visibility = str(b.visibility) === 'private' || access.space.kind === 'personal' ? 'private' : str(b.visibility) === 'space' ? 'space' : (s.visibility as string);
  const tx = new Tx(c.env);
  tx.raw(`UPDATE knowledge_sources SET title = ?, tags = ?, visibility = ?, updated_at = ? WHERE id = ?`, cleanLine(str(b.title), 120) || s.title, b.tags !== undefined ? cleanLine(str(b.tags), 200) : s.tags, visibility, Date.now(), s.id);
  audit(tx, { workspaceId: a.workspace.id, spaceId: s.space_id as string, actor: { kind: 'user', id: a.user.id }, action: 'knowledge.settings', subject: { type: 'knowledge', id: s.id as string }, summary: `공개 범위 ${visibility}` });
  await tx.commit();
  return c.json({ ok: true });
});

