const CONTENT_TYPE: Record<string, string> = { json: 'application/json', csv: 'text/csv', ...DOC_MIME };
const extOf = (name: string) => (name.match(/\.([a-z0-9]+)$/i)?.[1] ?? '').toLowerCase();

r.post('/w/:w/spaces/:s/uploads', async (c) => {
  const a = await sp(c);
