  if (c.env.FILE_UPLOADS === 'off') throw new ApiError(403, 'uploads_off', '파일 업로드가 꺼져 있습니다. 내용을 직접 붙여 넣어 주세요.');
  const b = await body(c);
  const name = cleanLine(str(b.name), 160);
  const size = Math.round(Number(b.size));
  const ext = extOf(name);
  const docs = documentsEnabled(c.env);
  if (FILE_POLICY.unsupported[ext]) throw new ApiError(415, 'unsupported_type', FILE_POLICY.unsupported[ext]!);
  const isDoc = isDocumentExt(ext);
  if (isDoc && !docs) throw new ApiError(415, 'unsupported_type', 'PDF·오피스 문서 읽기가 지금 꺼져 있습니다. 텍스트로 붙여 넣거나 TXT·Markdown·CSV·JSON 으로 올려 주세요.');
  if (!isDoc && !FILE_POLICY.extensions.includes(ext))
    throw new ApiError(415, 'unsupported_type', docs ? 'TXT·Markdown·CSV·JSON·PDF·워드(docx)·엑셀(xlsx·xls)·ODT·ODS·HTML 파일만 받습니다.' : '텍스트(.txt)·Markdown(.md)·CSV·JSON 파일만 받습니다.');
  const limit = isDoc ? FILE_POLICY.maxDocBytes : FILE_POLICY.maxBytes;
  if (!(size > 0) || size > limit) throw new ApiError(413, 'too_large', `${isDoc ? '문서' : '텍스트'} 파일은 ${limit / 1024 / 1024}MB 까지입니다.`);
  const id = newId();
  const tx = new Tx(c.env);
  // 용량 예약 — 한도를 넘으면 0행 → 되돌림
  tx.raw(`UPDATE workspaces SET storage_used = storage_used + ? WHERE id = ? AND storage_used + ? <= storage_limit`, size, a.workspace.id, size).expect();
  tx.raw(`INSERT INTO upload_intents (id, workspace_id, space_id, user_id, name, declared_size, temp_key, status, expires_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?)`, id, a.workspace.id, a.space.id, a.user.id, name, size, `tmp/${a.workspace.id}/${id}`, Date.now() + 15 * 60_000, Date.now());
  await tx.commit('저장 용량 한도를 넘습니다.');
  return c.json({ id, uploadUrl: `/api/w/${a.workspace.id}/uploads/${id}` }, 201);
});

