  return c.json({ ok: true, size: buf.byteLength });
});

async function reject(env: Env, i: Record<string, unknown>, reason: string) {
  await env.FILES.delete(i.temp_key as string).catch(() => {});
  await env.DB.batch([
    env.DB.prepare(`UPDATE upload_intents SET status = 'rejected', reject_reason = ? WHERE id = ? AND status = 'uploaded'`).bind(reason, i.id),
    env.DB.prepare(`UPDATE workspaces SET storage_used = MAX(0, storage_used - ?) WHERE id = ?`).bind(i.declared_size, i.workspace_id),
  ]);
  return new ApiError(422, 'file_rejected', reason);
}

