import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useState } from 'react';

export class ApiError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: Record<string, string>,
    public data?: Record<string, unknown>,
  ) {
    super(message);
  }
}

type Init = { method?: 'GET' | 'POST' | 'PUT' | 'DELETE'; json?: unknown; raw?: Blob | ArrayBuffer; headers?: Record<string, string> };

export async function api<T = unknown>(path: string, init: Init = {}): Promise<T> {
  const method = init.method ?? (init.json !== undefined || init.raw ? 'POST' : 'GET');
  let res: Response;
  try {
    res = await fetch(path, {
      method,
      credentials: 'same-origin',
      headers: { ...(init.json !== undefined ? { 'Content-Type': 'application/json' } : init.raw ? { 'Content-Type': 'application/octet-stream' } : {}), ...(init.headers ?? {}) },
      body: init.raw ?? (init.json !== undefined ? JSON.stringify(init.json) : undefined),
    });
  } catch {
    throw new ApiError(0, 'network', '인터넷 연결을 확인해 주세요.');
  }
  const type = res.headers.get('Content-Type') ?? '';
  const data = type.includes('application/json') ? await res.json().catch(() => null) : null;
  if (!res.ok) {
    const e = (data?.error ?? data) as { code?: string; message?: string; fields?: Record<string, string> } | null;
    if (res.status === 401) throw new ApiError(401, 'unauthenticated', '로그인이 필요합니다.');
    throw new ApiError(res.status, e?.code ?? 'error', e?.message ?? '처리하지 못했습니다. 잠시 후 다시 시도해 주세요.', e?.fields, data ?? undefined);
  }
  return data as T;
}

export function useApi<T>(path: string | null, opts: { refetchInterval?: number | false } = {}) {
  return useQuery<T, ApiError>({
    queryKey: [path],
    queryFn: () => api<T>(path!),
    enabled: !!path,
    retry: (n, e) => n < 1 && (e as ApiError).status >= 500,
    refetchInterval: opts.refetchInterval,
  });
}

/** 버튼 하나의 처리 — 진행 중·오류 상태와, 끝나면 관련 화면 다시 읽기 */
export function useAction() {
  const qc = useQueryClient();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<ApiError | null>(null);
  const run = useCallback(
    async <T,>(fn: () => Promise<T>, opts: { invalidate?: string[] } = {}): Promise<T | undefined> => {
      setBusy(true);
      setError(null);
      try {
        const out = await fn();
        if (opts.invalidate) await Promise.all(opts.invalidate.map((p) => qc.invalidateQueries({ predicate: (q) => String(q.queryKey[0] ?? '').startsWith(p) })));
        else await qc.invalidateQueries();
        return out;
      } catch (e) {
        setError(e instanceof ApiError ? e : new ApiError(0, 'error', String(e)));
        return undefined;
      } finally {
        setBusy(false);
      }
    },
    [qc],
  );
  return { run, busy, error, setError };
}

