};

export function Timeline({ events }: { events: RunEvent[] }) {
  if (!events.length) return <p className="small muted">아직 기록이 없습니다.</p>;
  return (
    <ol className="timeline" aria-label="실행 기록">
      {events.map((e) => {
        const f = EV[e.type]?.(e.data) ?? { text: e.type };
        return (
          <li key={e.seq} className={f.tone ? `t-${f.tone}` : ''}>
            <div className="timeline__time">{fmtTime(e.at)}</div>
            <div className="timeline__body">{f.text}</div>
          </li>
        );
      })}
    </ol>
  );
}

interface ApprovalItem {
  id: string;
  runId: string;
  tool: string;
  connection: string;
  args: Record<string, unknown>;
  argsHash: string;
  targets: string[];
  expiresAt: number;
  agent: string;
}

/** 승인 카드 — 정확한 도구·대상·인자를 보여 주고, 본 그대로의 인자 해시로 결정한다 */
export function ApprovalCard({ ws, a }: { ws: string; a: ApprovalItem }) {
  const act = useAction();
  return (
    <div className="state-box state-box--warn approval">
      <h3>
        <RiskChip risk="write" /> {a.connection} / {a.tool}
      </h3>
      {a.targets.some((t) => !t.includes(' / ')) && (
        <div>
          <p className="small muted">대상</p>
          <div className="approval__targets">
            {a.targets.map((t) => (
              <span key={t}>{t}</span>
            ))}
          </div>
        </div>
      )}
      <dl className="approval__args" aria-label="실행할 인자">
        {Object.entries(a.args)
          .slice(0, 6)
          .map(([k, v]) => (
            <div key={k} style={{ display: 'contents' }}>
              <dt>{k}</dt>
              <dd>{typeof v === 'string' ? (v.length > 400 ? `${v.slice(0, 400)}…` : v) : JSON.stringify(v)}</dd>
            </div>
          ))}
      </dl>
      <details>
        <summary className="small">정확한 인자 보기</summary>
        <Json value={a.args} />
        <p className="micro muted mono">인자 해시 {a.argsHash.slice(0, 16)}…</p>
      </details>
      <p className="micro muted">
        {a.agent} · 승인 기한 {until(a.expiresAt)}. 승인하면 이 인자 그대로 한 번만 실행합니다. 인자가 바뀌면 다시 승인을 받습니다.
      </p>
      <ErrorNotice error={act.error} />
      <div className="approval__actions">
        <button type="button" className="btn btn-primary btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/approvals/${a.id}/decisions`, { json: { decision: 'approve', argsHash: a.argsHash } }))}>
          이 내용으로 승인
        </button>
        <button type="button" className="btn btn-danger btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/approvals/${a.id}/decisions`, { json: { decision: 'reject', argsHash: a.argsHash } }))}>
          거절
        </button>
      </div>
    </div>
  );
}

export interface RunDetail {
  run: {
    id: string;
    status: string;
    outcome: string | null;
    errorCode: string | null;
    errorMessage: string;
    trigger: string;
    conversationId: string | null;
    spaceId: string;
    mine: boolean;
    canAct: boolean;
    createdAt: number;
    finishedAt: number | null;
    modelCalls: number;
    toolCalls: number;
    spentMicros: number;
    budgetMicros: number;
    costPending: boolean;
  };
  agent: { id: string; name: string; version: number; draft: boolean; configHash: string };
  model: { provider: string; model: string; scope: string } | null;
  limits: { modelCalls: number; toolCalls: number; budgetMicros: number };
  invocations: { id: string; tool_name: string; risk: string; status: string; error: string; args: Record<string, unknown>; targets: string[]; result: string | null }[];
  artifacts: { id: string; title: string; format: string; size: number; sha256: string }[];
  evidence: { sourceId: string; version: number; title: string; available: boolean }[];
  answer: string | null;
}

/** 실행 상태별 다음 행동(입력·연결·한도·결과 확인·중지) */
export function RunActions({ ws, d }: { ws: string; d: RunDetail }) {
  const act = useAction();
  const [answer, setAnswer] = useState('');
  const r = d.run;
  const st = r.status as RunStatus;
  if (!r.canAct) return null;
  const unknown = d.invocations.filter((i) => i.status === 'outcome_unknown');
  return (
    <div className="stack-gap">
      <ErrorNotice error={act.error} />
      {st === 'waiting_input' && (
        <form
          className="state-box state-box--warn"
          onSubmit={async (e) => {
            e.preventDefault();
            if (await act.run(() => api(`/api/w/${ws}/runs/${r.id}/inputs`, { json: { content: answer } }))) setAnswer('');
          }}
        >
          <h3>정보가 더 필요합니다</h3>
          <label className="visually-hidden" htmlFor={`ans-${r.id}`}>
            답
          </label>
          <textarea id={`ans-${r.id}`} className="textarea" rows={3} value={answer} onChange={(e) => setAnswer(e.target.value)} required />
          <div className="btn-row">
            <button className="btn btn-primary btn-sm" disabled={act.busy}>
              답 보내고 이어 가기
            </button>
          </div>
        </form>
      )}
      {st === 'waiting_connection' && (
        <div className="state-box state-box--warn">
          <h3>연결을 다시 인증해야 합니다</h3>
          <p className="small">{r.errorMessage || '외부 도구 연결이 만료되었거나 재인증이 필요합니다.'}</p>
          <div className="btn-row">
            <Link className="btn btn-secondary btn-sm" to={`/app/w/${ws}/connections`}>
              연결 화면으로
            </Link>
            <button type="button" className="btn btn-primary btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/runs/${r.id}/retry`, { json: {} }))}>
              고쳤어요 — 이어 가기
            </button>
          </div>
        </div>
      )}
      {st === 'paused_budget' && (
        <div className="state-box state-box--warn">
          <h3>한도에 닿아 멈췄습니다</h3>
          <p className="small">
            {r.errorMessage} 지금까지 <Money micros={r.spentMicros} pending={r.costPending} /> 사용 / 실행 예산 <Money micros={r.budgetMicros} />. 지금까지의 결과는 남아 있습니다.
          </p>
          <div className="btn-row">
            <button type="button" className="btn btn-secondary btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/runs/${r.id}/retry`, { json: { addBudgetMicros: Math.round(r.budgetMicros / 2), addModelCalls: 2, addToolCalls: 4 } }))}>
              한도 조금 늘려 이어 가기
            </button>
            <button type="button" className="btn btn-ghost btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/runs/${r.id}/cancel`, { json: {} }))}>
              여기서 끝내기
            </button>
          </div>
        </div>
      )}
      {st === 'waiting_reconciliation' &&
        unknown.map((i) => (
          <div key={i.id} className="state-box state-box--danger">
            <h3>결과 확인 필요: {i.tool_name}</h3>
            <p className="small">외부 동작이 실제로 실행됐는지 확인하지 못했습니다. 자동으로 다시 보내지 않습니다. 외부 서비스에서 확인한 뒤 결과를 알려 주세요.</p>
            <div className="btn-row">
              <button type="button" className="btn btn-secondary btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/runs/${r.id}/reconcile`, { json: { invocationId: i.id, outcome: 'done' } }))}>
                실행됐어요
              </button>
              <button type="button" className="btn btn-secondary btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/runs/${r.id}/reconcile`, { json: { invocationId: i.id, outcome: 'not_done' } }))}>
                실행 안 됐어요
              </button>
            </div>
          </div>
        ))}
      {['queued', 'running', 'waiting_input', 'waiting_approval', 'waiting_connection', 'waiting_reconciliation'].includes(st) && (
        <div className="btn-row">
          <button type="button" className="btn btn-ghost btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/runs/${r.id}/cancel`, { json: {} }))}>
            실행 중지
          </button>
          <span className="micro muted">중지는 새 동작을 막을 뿐, 이미 보낸 것을 되돌리지 않습니다.</span>
        </div>
      )}
      {['failed', 'cancelled', 'expired'].includes(st) && (
        <div className="btn-row">
          <button type="button" className="btn btn-secondary btn-sm" disabled={act.busy} onClick={() => act.run(() => api(`/api/w/${ws}/runs/${r.id}/retry`, { json: {} }))}>
            새 실행으로 다시 시도
          </button>
        </div>
      )}
    </div>
  );
}

/** 오른쪽 실행 패널 */
export function RunPanel({ ws, runId, onClose }: { ws: string; runId: string; onClose: () => void }) {
  const { events } = useRunEvents(ws, runId);
  const d = useApi<RunDetail>(`/api/w/${ws}/runs/${runId}`);
  const approvals = useApi<{ approvals: ApprovalItem[] }>(`/api/w/${ws}/approvals`);
  const mine = (approvals.data?.approvals ?? []).filter((a) => a.runId === runId);
  const run = d.data?.run;
  return (
    <aside className="panel" aria-label="실행 패널">
      <div className="panel__head">
        <h2>실행</h2>
        <div className="btn-row">
          <Link className="btn btn-ghost btn-sm" to={`/app/w/${ws}/runs/${runId}`}>
            자세히
          </Link>
          <button type="button" className="btn btn-ghost btn-sm" onClick={onClose} aria-label="실행 패널 닫기">
            ✕
          </button>
        </div>
      </div>
      {run && (
        <>
          <div className="run-card__top">
            <RunPill status={run.status} outcome={run.outcome} />
            <span className="small muted">
              {d.data!.agent.name} v{d.data!.agent.version}
              {d.data!.agent.draft ? ' (초안 시험)' : ''}
            </span>
          </div>
          {RUN_STATUS[run.status as RunStatus]?.hint && <p className="small muted">{RUN_STATUS[run.status as RunStatus].hint}</p>}
          {run.errorCode && run.status === 'failed' && (
            <div className="state-box state-box--danger">
              <h3>{RUN_ERROR[run.errorCode as RunErrorCode]?.label ?? run.errorCode}</h3>
              <p className="small">{run.errorMessage}</p>
              <p className="small muted">{RUN_ERROR[run.errorCode as RunErrorCode]?.next}</p>
            </div>
          )}
          {mine.map((a) => (
            <ApprovalCard key={a.id} ws={ws} a={a} />
          ))}
          <RunActions ws={ws} d={d.data!} />
          <dl className="kv">
            <dt>모델</dt>
            <dd>{d.data!.model ? `${d.data!.model.model}` : '-'}</dd>
            <dt>호출</dt>
            <dd>
              모델 {run.modelCalls}/{d.data!.limits?.modelCalls} · 도구 {run.toolCalls}/{d.data!.limits?.toolCalls}
            </dd>
            <dt>비용</dt>
            <dd>
              <Money micros={run.spentMicros} pending={run.costPending} /> / <Money micros={run.budgetMicros} />
            </dd>
            {run.finishedAt && (
              <>
                <dt>걸린 시간</dt>
                <dd className="t-num">{((run.finishedAt - run.createdAt) / 1000).toFixed(1)}초</dd>
              </>
            )}
          </dl>
          {d.data!.artifacts.length > 0 && (
            <div>
              <p className="small muted">결과물</p>
              <ul className="small">
                {d.data!.artifacts.map((a) => (
                  <li key={a.id}>
                    <a href={`/api/w/${ws}/artifacts/${a.id}/content`}>{a.title}</a> <span className="muted">({a.format})</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
          {d.data!.evidence.length > 0 && (
            <div>
              <p className="small muted">근거로 읽은 자료</p>
              <ul className="small">
                {d.data!.evidence.map((e) => (
                  <li key={e.sourceId} className={e.available ? '' : 'muted'}>
                    {e.title} {e.available && <span className="muted">v{e.version}</span>}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </>
      )}
      <div>
        <p className="small muted" style={{ marginBottom: 6 }}>
          진행 기록
        </p>
        <Timeline events={events} />
      </div>
    </aside>
  );
}

