/**
 * 예약 작업 — 실제 실행 주체(나의 위임 또는 팀 서비스 주체)와 허용 작업을 보여 주고 확인받아 등록한다.
 * 쓰기 도구는 대상(수신처 등)을 적어 위임한 것만 승인 없이 실행된다 — 그 밖의 쓰기는 실행 때 승인함으로 간다.
 */
import { router, body, str, num, ws, sp, type Ctx } from '../app';
import { Tx } from '../db/client';
import { bad, conflict, forbidden, notFound } from '../lib/errors';
import { cleanLine, cleanText, newId, parseJson } from '../lib/util';
import { requireSpace, spaceAccessIn, visibleSpaces } from '../policies/access';
import { audit } from '../domain/audit';
import { agentUsable, type AgentRow } from '../domain/runs';
import { assertNotPersonalForService, delegationTools, nextAfter, planSchedule, runScheduleNow, type DelegationToolInput } from '../domain/schedules';
import type { PinnedTool } from '../domain/tools';
import { fmtWall } from '../../shared/cron';
import { canSpace } from '../../shared/domain';

const r = router();

r.post('/w/:w/schedules/preview', async (c) => {
  await ws(c);
  const b = await body(c);
  const { plan, next } = planSchedule({ kind: b.kind, repeat: b.repeat, runAtLocal: b.runAtLocal, timezone: b.timezone, gapPolicy: b.gapPolicy });
  return c.json({ plan, next: next.map((n) => ({ utc: n.utc, utcIso: new Date(n.utc).toISOString(), local: fmtWall(n.utc, plan.timezone), note: n.note ?? null })) });
});

async function parseDelegationInput(env: Env, workspaceId: string, b: Record<string, unknown>, pinned: PinnedTool[]) {
  const writes = (Array.isArray(b.writes) ? (b.writes as Record<string, unknown>[]) : []).map((w) => ({ connectionId: str(w.connectionId), name: str(w.name), targets: Array.isArray(w.targets) ? (w.targets as unknown[]).map(String) : [] })) as DelegationToolInput[];
  // 메일 위임 대상은 워크스페이스 구성원만
  for (const w of writes.filter((x) => x.connectionId === 'builtin' && x.name === 'send_email')) {
    const members = new Set(((await env.DB.prepare(`SELECT u.email FROM workspace_members m JOIN user u ON u.id = m.user_id WHERE m.workspace_id = ? AND m.status = 'active'`).bind(workspaceId).all<{ email: string }>()).results ?? []).map((x) => `to: ${x.email.toLowerCase()}`));
    if ((w.targets ?? []).some((t) => !members.has(t.trim().toLowerCase()))) throw bad('메일 위임 수신처는 이 워크스페이스 구성원만 고를 수 있습니다(형식: to: 주소).');
  }
  return delegationTools(pinned, writes);
}

r.post('/w/:w/schedules', async (c) => {
  const b = await body(c);
  const a = await sp(c, str(b.spaceId));
  requireSpace(a, 'build', '이 공간에서 예약을 만들 권한이 없습니다.');
  requireSpace(a, 'run');
  const principalKind = str(b.principalKind) === 'service' ? 'service' : 'personal';
  assertNotPersonalForService(principalKind, a.space.kind);
  if (principalKind === 'service' && a.spaceRole !== 'manager') throw forbidden('팀 자동화(서비스 주체)는 공간 관리자만 위임할 수 있습니다.');
  const agent = await c.env.DB.prepare(`SELECT * FROM agents WHERE id = ? AND workspace_id = ?`).bind(str(b.agentId), a.workspace.id).first<AgentRow>();
  if (!agent || !agent.published_version_id || agent.status !== 'published' || !agentUsable(agent, a.user.id, a.space.id)) throw notFound('예약에 쓸 수 있는 발행된 에이전트가 아닙니다.');
  const version = await c.env.DB.prepare(`SELECT id, pinned_tools_json FROM agent_versions WHERE id = ?`).bind(agent.published_version_id).first<{ id: string; pinned_tools_json: string }>();
  const { plan, next } = planSchedule({ kind: b.kind, repeat: b.repeat, runAtLocal: b.runAtLocal, timezone: b.timezone, gapPolicy: b.gapPolicy });
  const name = cleanLine(str(b.name), 60) || agent.name;
  const input = cleanText(str(b.input), 5000);
  if (!input) throw bad('예약 실행 때 넣을 입력을 적어 주세요.');
  const tools = await parseDelegationInput(c.env, a.workspace.id, b, parseJson<PinnedTool[]>(version!.pinned_tools_json, []));
  const expiresDays = Math.min(365, Math.max(1, Math.round(num(b.expiresInDays, 90))));
  const maxRuns = Math.min(1000, Math.max(1, Math.round(num(b.maxRuns, plan.kind === 'once' ? 1 : 100))));
  const runBudget = Math.min(5_000_000, Math.max(10_000, Math.round(num(b.runBudgetMicros, 200_000))));
  const monthly = Math.min(50_000_000, Math.max(runBudget, Math.round(num(b.monthlyBudgetMicros, runBudget * 10))));
  const endAt = typeof b.endAt === 'number' && b.endAt > Date.now() ? b.endAt : null;
  const now = Date.now();
  const id = newId();
  const dg = newId();
  const conv = newId();
  const tx = new Tx(c.env);
  tx.raw(
    `INSERT INTO delegation_grants (id, workspace_id, space_id, kind, grantor_user_id, agent_version_id, tools_json, max_runs, max_cost_micros, expires_at, policy_version, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?)`,
    dg,
    a.workspace.id,
    a.space.id,
    principalKind,
    a.user.id,
    version!.id,
    JSON.stringify(tools),
    maxRuns,
    monthly,
    now + expiresDays * 86_400_000,
    a.workspace.policyVersion,
    now,
  );
  tx.raw(`INSERT INTO conversations (id, workspace_id, space_id, owner_user_id, agent_id, title, visibility, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)`, conv, a.workspace.id, a.space.id, a.user.id, agent.id, `예약: ${name}`, principalKind === 'service' ? 'space' : 'private', now, now);
  tx.raw(
    `INSERT INTO schedules (id, workspace_id, space_id, name, agent_id, agent_version_id, follow_latest, version, owner_user_id, principal_kind, delegation_id, conversation_id, kind, cron, run_at_local, timezone, gap_policy, input, status, next_run_at, end_at, max_runs, run_budget_micros, monthly_budget_micros, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?, ?)`,
    id,
    a.workspace.id,
    a.space.id,
    name,
    agent.id,
    version!.id,
    b.followLatest === true ? 1 : 0,
    a.user.id,
    principalKind,
    dg,
    conv,
    plan.kind,
    plan.cron,
    plan.runAtLocal,
    plan.timezone,
    plan.gapPolicy,
    input,
    next[0]!.utc,
    endAt,
    maxRuns,
    runBudget,
    monthly,
    now,
    now,
  );
  audit(tx, { workspaceId: a.workspace.id, spaceId: a.space.id, actor: { kind: 'user', id: a.user.id }, action: 'schedule.create', subject: { type: 'schedule', id }, summary: `예약 ${name}: ${plan.kind === 'once' ? plan.runAtLocal : plan.cron} ${plan.timezone}, 위임 도구 ${tools.length}개(쓰기 ${tools.filter((t) => t.risk === 'write').length}), ${expiresDays}일` });
  await tx.commit();
  return c.json({ id, nextRunAt: next[0]!.utc }, 201);
});

r.get('/w/:w/schedules', async (c) => {
  const a = await ws(c);
  const spaces = await visibleSpaces(c.env, a);
  const ids = spaces.map((s) => s.id);
  if (!ids.length) return c.json({ schedules: [] });
  const rows = await c.env.DB.prepare(
    `SELECT s.id, s.name, s.space_id, s.kind, s.cron, s.run_at_local, s.timezone, s.status, s.status_reason, s.next_run_at, s.run_count, s.consecutive_failures, s.principal_kind, s.owner_user_id, s.run_budget_micros, s.monthly_budget_micros, s.follow_latest,
            a.name AS agent_name, av.version AS agent_version, u.name AS owner_name, r.status AS last_status
       FROM schedules s JOIN agents a ON a.id = s.agent_id JOIN agent_versions av ON av.id = s.agent_version_id JOIN user u ON u.id = s.owner_user_id LEFT JOIN runs r ON r.id = s.last_run_id
      WHERE s.workspace_id = ? AND s.space_id IN (${ids.map(() => '?').join(',')}) AND (s.owner_user_id = ? OR s.principal_kind = 'service') AND s.status != 'ended'
      ORDER BY s.status = 'active' DESC, s.next_run_at`,
  )
    .bind(a.workspace.id, ...ids, a.user.id)
    .all<Record<string, unknown>>();
  return c.json({ schedules: (rows.results ?? []).map((s) => ({ ...s, nextLocal: s.next_run_at ? fmtWall(s.next_run_at as number, s.timezone as string) : null, mine: s.owner_user_id === a.user.id })) });
});

async function loadSchedule(c: Ctx, manage = false) {
  const a = await ws(c);
  const s = await c.env.DB.prepare(`SELECT * FROM schedules WHERE id = ? AND workspace_id = ?`).bind(c.req.param('id'), a.workspace.id).first<Record<string, unknown>>();
  if (!s) throw notFound();
  const access = await spaceAccessIn(c.env, a, s.space_id as string);
  const mine = s.owner_user_id === a.user.id;
  if (!mine && s.principal_kind !== 'service') throw notFound();
  if (manage && !mine && !(s.principal_kind === 'service' && access.spaceRole === 'manager')) throw forbidden('예약을 바꿀 권한이 없습니다.');
  return { a, s, access, mine };
}

r.get('/w/:w/schedules/:id', async (c) => {
  const { s, access, mine } = await loadSchedule(c);
  const occ = await c.env.DB.prepare(`SELECT o.id, o.scheduled_for, o.status, o.reason, o.skipped_count, o.run_id, o.schedule_version, r.status AS run_status, r.started_at, r.finished_at FROM schedule_occurrences o LEFT JOIN runs r ON r.id = o.run_id WHERE o.schedule_id = ? ORDER BY o.scheduled_for DESC LIMIT 30`).bind(s.id).all<Record<string, unknown>>();
  const d = await c.env.DB.prepare(`SELECT id, kind, tools_json, max_runs, used_runs, max_cost_micros, expires_at, status, status_reason, created_at FROM delegation_grants WHERE id = ?`).bind(s.delegation_id).first<Record<string, unknown>>();
  const upcoming: { utc: number; local: string }[] = [];
  let t = (s.next_run_at as number | null) ?? null;
  for (let i = 0; i < 5 && t; i++) {
    upcoming.push({ utc: t, local: fmtWall(t, s.timezone as string) });
    t = nextAfter({ kind: s.kind as string, cron: s.cron as string | null, timezone: s.timezone as string, gap_policy: s.gap_policy as string }, t);
  }
  const agent = await c.env.DB.prepare(`SELECT a.name, a.published_version_id, av.version FROM agents a JOIN agent_versions av ON av.id = ? WHERE a.id = ?`).bind(s.agent_version_id, s.agent_id).first<Record<string, unknown>>();
  return c.json({
    schedule: { ...s, mine, canManage: mine || (s.principal_kind === 'service' && access.spaceRole === 'manager') },
    agent,
    newerVersionAvailable: agent?.published_version_id !== s.agent_version_id,
    delegation: d ? { ...d, tools: parseJson(d.tools_json as string, []), tools_json: undefined } : null,
    upcoming: upcoming.map((u) => ({ ...u, utcIso: new Date(u.utc).toISOString() })),
    occurrences: occ.results,
    canRun: canSpace(access.role, access.spaceRole, 'run'),
  });
});

r.post('/w/:w/schedules/:id/pause', async (c) => {
  const { a, s } = await loadSchedule(c, true);
  const tx = new Tx(c.env);
