/**
 * 실행 실시간 보기 — run_events 를 SSE 로 받는다. 끊기면 브라우저가 Last-Event-ID 로 이어 받고,
 * 새로 열면 지금까지 받은 마지막 seq 이후만 요청한다. seq 로 중복을 걸러 같은 사건을 두 번 보이지 않는다.
 * 창을 닫아도 실행은 서버에서 계속된다.
 */
import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router';
import { useQueryClient } from '@tanstack/react-query';
import { api, useAction, useApi } from '../../lib/api';
import type { RunEvent } from '../../lib/types';
import { ErrorNotice, Json, Money, RiskChip, RunPill } from '../../components/ui';
import { fmtTime, fmtMicros, until } from '../../lib/format';
import { RUN_ERROR, RUN_STATUS, TERMINAL_RUN, type RunErrorCode, type RunStatus } from '../../../shared/domain';

export function useRunEvents(ws: string, runId: string | null) {
  const [events, setEvents] = useState<RunEvent[]>([]);
  const [status, setStatus] = useState<string | null>(null);
  const seqRef = useRef(0);
  const qc = useQueryClient();
  useEffect(() => {
    setEvents([]);
    seqRef.current = 0;
    setStatus(null);
    if (!runId) return;
    let es: EventSource | null = null;
    let poll: ReturnType<typeof setInterval> | null = null;
    let closed = false;
    const add = (list: RunEvent[]) => {
      const fresh = list.filter((e) => e.seq > seqRef.current);
      if (!fresh.length) return;
      seqRef.current = fresh[fresh.length - 1]!.seq;
      setEvents((prev) => {
        const seen = new Set(prev.map((p) => p.seq));
        return [...prev, ...fresh.filter((e) => !seen.has(e.seq))];
      });
      const last = fresh[fresh.length - 1]!.type;
      if (['succeeded', 'failed', 'cancelled', 'expired', 'approval_required', 'input_required', 'connection_required', 'budget_paused', 'reconciliation_required', 'cancel_requested', 'resumed', 'approval_decided', 'input_received', 'reconciled'].includes(last)) {
        qc.invalidateQueries({ predicate: (q) => /\/(conversations|runs|approvals)\b|\/api\/w\/[^/]+$/.test(String(q.queryKey[0] ?? '')) });
      }
    };
    const startPoll = () => {
      if (poll) return;
      poll = setInterval(async () => {
        try {
          const r = await api<{ events: RunEvent[]; status: string }>(`/api/w/${ws}/runs/${runId}/events?after=${seqRef.current}`);
          add(r.events);
          setStatus(r.status);
          if (TERMINAL_RUN.includes(r.status as RunStatus) && poll) {
            clearInterval(poll);
            poll = null;
          }
        } catch {
          /* 다음 차례에 */
        }
      }, 2500);
    };
    if (typeof EventSource !== 'undefined') {
      es = new EventSource(`/api/w/${ws}/runs/${runId}/events?after=0`);
      es.addEventListener('run', (m) => {
        try {
          add([JSON.parse((m as MessageEvent).data)]);
        } catch {
          /* 무시 */
        }
      });
      es.addEventListener('end', (m) => {
        try {
          setStatus(JSON.parse((m as MessageEvent).data).status);
        } catch {
          /* 무시 */
        }
        es?.close();
        qc.invalidateQueries({ predicate: (q) => /\/(conversations|runs)\b/.test(String(q.queryKey[0] ?? '')) });
      });
      es.onerror = () => {
        // 서버가 25초마다 닫는다 — 브라우저가 Last-Event-ID 로 다시 붙는다. 영구 실패(4xx)면 폴링으로
        if (es && es.readyState === EventSource.CLOSED && !closed) startPoll();
      };
    } else startPoll();
    return () => {
      closed = true;
      es?.close();
      if (poll) clearInterval(poll);
    };
  }, [ws, runId, qc]);
  return { events, status };
}

