async function dueNow(p: Person, scheduleId: string, ago = 60_000) {
  await sql(p, `UPDATE schedules SET next_run_at = ? WHERE id = ?`, [Date.now() - ago, scheduleId]);
}
const occ = async (p: Person, id: string) => (await p.api.get(`/api/w/${p.ws}/schedules/${id}`)).occurrences as { status: string; run_id: string | null; skipped_count: number; scheduled_for: number }[];

test('같은 회차를 두 scheduler 가 동시에 봐도 실행은 하나 — 세션 없이 위임으로(39)', async () => {
  const p = await person('s39');
  await addModel(p);
  const { agentId } = await publishAgent(p);
  await script('s39', [{ text: '예약 결과' }]);
  const s = await p.api.post(`/api/w/${p.ws}/schedules`, { spaceId: p.space, agentId, input: '[[script:s39]] 예약 실행', kind: 'recurring', repeat: { every: 'day', time: '09:00' } }, 201);
  await dueNow(p, s.id);
  await Promise.all([cron(p), cron(p), cron(p)]);
  const o = await occ(p, s.id);
  expect(o.filter((x) => x.run_id)).toHaveLength(1);
  const runs = await sql(p, `SELECT id, principal_kind, trigger, delegation_id FROM runs WHERE schedule_id = ?`, [s.id]);
  expect(runs.results).toHaveLength(1);
  expect(runs.results[0]).toMatchObject({ principal_kind: 'delegation', trigger: 'schedule' });
  const d = await waitRun(p, runs.results[0]!.id as string);
  expect(d.run.status).toBe('succeeded');
  // 다음 실행 시각은 미래로
  const next = Number((await sql(p, `SELECT next_run_at FROM schedules WHERE id = ?`, [s.id])).results[0]!.next_run_at);
  expect(next).toBeGreaterThan(Date.now());
  // 결과 알림 메일
  expect((await mailsTo(p.email)).some((m) => m.subject.includes('예약 실행 완료'))).toBe(true);
});

