  if (!(c.req.header('Content-Type') ?? '').startsWith('application/json')) throw new ApiError(415, 'invalid', 'JSON 으로 보내 주세요.');
  const len = Number(c.req.header('Content-Length') ?? '0');
  if (len > MAX_JSON) throw new ApiError(413, 'too_large', '내용이 너무 깁니다.');
  const text = await c.req.text();
  if (text.length > MAX_JSON) throw new ApiError(413, 'too_large', '내용이 너무 깁니다.');
  try {
    const v = JSON.parse(text);
    if (!v || typeof v !== 'object' || Array.isArray(v)) throw new Error();
    return v as Record<string, unknown>;
  } catch {
    throw bad('요청 형식이 올바르지 않습니다.');
  }
