/** API 오류 — 화면은 code 로 분기하고 message 를 그대로 보여 준다 */
export class ApiError extends Error {
  constructor(
    public status: 400 | 401 | 402 | 403 | 404 | 409 | 410 | 413 | 415 | 422 | 429 | 500 | 502 | 503,
    public code: string,
    message: string,
    public fields?: Record<string, string>,
  ) {
    super(message);
  }
}

export const bad = (message: string, fields?: Record<string, string>) => new ApiError(400, 'invalid', message, fields);
export const forbidden = (message = '이 작업을 할 권한이 없습니다.', code = 'forbidden') => new ApiError(403, code, message);
/** 볼 수 없는 것은 있는지도 알리지 않는다 */
export const notFound = (message = '찾을 수 없습니다.') => new ApiError(404, 'not_found', message);
export const conflict = (message: string, code = 'conflict') => new ApiError(409, code, message);
